import {validateRecurringState} from './recurring.js';
import {validateCard,saveCard,prepareTransaction} from './cards.js';
import {validateInstallment} from './installments.js';
import {validateEmployment} from './employment.js';
export const KEY='castor-wallet-v1';
export const methods=['PIX','Débito','Dinheiro','Cartão de crédito'];
export const credit=t=>t.method==='Cartão de crédito';
export const monthOf=date=>date.slice(0,7);
export function validDate(date){return /^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date+'T12:00:00Z'))&&new Date(date+'T12:00:00Z').toISOString().slice(0,10)===date;}
export function addMonth(month,n=1){const [y,m]=month.split('-').map(Number);return new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7);}
export function invoiceMonth(date,closing){return Number(date.slice(8))>closing?addMonth(monthOf(date)):monthOf(date);}
export function dueDate(month,card){const dueMonth=card.due<=card.closing?addMonth(month):month;const [y,m]=dueMonth.split('-').map(Number);const day=Math.min(card.due,new Date(Date.UTC(y,m,0)).getUTCDate());return `${dueMonth}-${String(day).padStart(2,'0')}`;}
export function validateTransaction(t,state){validateInstallment(t);if(t.paidDate!==undefined&&!validDate(t.paidDate))throw Error('Informe uma data de pagamento válida.');if(!validDate(t.date))throw Error('Informe uma data válida.');if(typeof t.description!=='string'||!t.description.trim())throw Error('Informe uma descrição.');if(!Number.isSafeInteger(t.amount)||t.amount<=0)throw Error('O valor deve ser maior que zero e ter até duas casas decimais.');if(!['income','expense'].includes(t.type)||!['paid','pending'].includes(t.status))throw Error('Tipo ou status inválido.');if(!state.categories.some(c=>c.id===t.category))throw Error('Escolha uma categoria válida.');if(!methods.includes(t.method))throw Error('Escolha um meio de pagamento válido.');if(credit(t)){if(t.type!=='expense')throw Error('Use PIX, débito ou dinheiro para receitas.');if(!state.cards.some(c=>c.id===t.card))throw Error('Selecione o cartão.');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(t.invoice))throw Error('Informe o mês da fatura.');if(t.status==='paid'&&!validDate(t.paidDate))throw Error('Informe a data de pagamento.');if(t.invoiceDueDate!==undefined&&!validDate(t.invoiceDueDate))throw Error('Vencimento da fatura inválido.');if(t.invoiceClosingDay!==undefined&&(!Number.isInteger(t.invoiceClosingDay)||t.invoiceClosingDay<1||t.invoiceClosingDay>28))throw Error('Fechamento da fatura inválido.');}return t;}
export function saveTransaction(state,t){validateTransaction(t,state);t=prepareTransaction(state,t);return {...state,transactions:state.transactions.some(x=>x.id===t.id)?state.transactions.map(x=>x.id===t.id?{...t}:x):[...state.transactions,{...t}]};}
export function removeTransaction(state,id){return {...state,transactions:state.transactions.filter(t=>t.id!==id)};}
export function settleInvoice(state,card,month,date){if(!validDate(date))throw Error('Informe a data de pagamento.');return {...state,transactions:state.transactions.map(t=>credit(t)&&t.card===card&&t.invoice===month&&t.status==='pending'?{...t,status:'paid',paidDate:date}:t)};}
export function cashDate(t){return t.paidDate||(credit(t)?undefined:t.date);}
export function balance(state,until){return state.opening+state.transactions.filter(t=>t.status==='paid'&&cashDate(t)&&cashDate(t)<=until).reduce((sum,t)=>sum+(t.type==='income'?t.amount:-t.amount),0);}
export function metrics(state,month){const rows=state.transactions.filter(t=>(credit(t)?t.invoice:monthOf(t.date))===month);const sum=predicate=>rows.filter(predicate).reduce((a,t)=>a+t.amount,0);return {income:sum(t=>t.type==='income'),expenses:sum(t=>t.type==='expense'),pending:sum(t=>t.type==='expense'&&t.status==='pending'),credit:sum(t=>t.type==='expense'&&credit(t)),cash:sum(t=>t.type==='expense'&&!credit(t)),rows};}
export function addCategory(state,name,color='#397868'){name=name.trim();if(!/^#[\da-f]{6}$/i.test(color))throw Error('Escolha uma cor válida.');if(!name)throw Error('Dê um nome à categoria.');if(state.categories.some(c=>c.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))throw Error('Essa categoria já existe.');return {...state,categories:[...state.categories,{id:crypto.randomUUID(),name,color}]};}
export function validateState(s){if(!s||s.version!==1||!Number.isSafeInteger(s.opening)||!Array.isArray(s.categories)||!Array.isArray(s.cards)||!Array.isArray(s.transactions))throw Error('Backup incompatível.');for(const list of [s.categories,s.cards,s.transactions]){if(list.some(x=>!x||typeof x.id!=='string')||new Set(list.map(x=>x.id)).size!==list.length)throw Error('Identificadores inválidos no backup.');}if(s.categories.some(c=>typeof c.name!=='string'||!c.name.trim()||!/^#[\da-f]{6}$/i.test(c.color)))throw Error('Categorias inválidas.');s.cards.forEach(validateCard);validateRecurringState(s);if(s.employment!=null)validateEmployment(s.employment,s);s.transactions.forEach(t=>validateTransaction(t,s));return s;}
export function demo(month){const categories=['Moradia','Alimentação','Transporte','Assinaturas','Lazer','Saúde','Salário','Outros'].map((name,i)=>({id:'cat'+i,name,color:['#568b78','#e7ae61','#7e97c4','#a494bd','#dc8e77','#6ea5a1','#8bbf90','#a6aaa2'][i]}));const s={version:1,opening:210000,categories,cards:[{id:'card1',name:'Meu cartão',closing:25,due:5}],transactions:[]};let n=0;const add=(m,day,description,amount,category,type='expense',method='PIX',status='paid')=>{const date=`${m}-${String(day).padStart(2,'0')}`;s.transactions.push({id:'demo'+n++,date,description,amount,category:'cat'+category,type,method,status,...(method==='Cartão de crédito'?{card:'card1',invoice:m,...(status==='paid'?{paidDate:dueDate(m,s.cards[0])}:{})}:{})});};for(let i=-5;i<=0;i++){const m=addMonth(month,i);add(m,5,'Salário',650000,6,'income');add(m,8,'Aluguel e condomínio',185000,0);add(m,12,'Mercado da semana',46290+i*1200,1);add(m,15,'Transporte e mobilidade',28000,2,'expense','Débito');add(m,10,'Streaming e música',6990,3,'expense','Cartão de crédito',i===0?'pending':'paid');add(m,18,'Restaurante com amigos',18500,4,'expense','Cartão de crédito',i===0?'pending':'paid');add(m,20,'Farmácia',12780,5,'expense','Cartão de crédito',i===0?'pending':'paid');if(i===0){add(m,22,'Internet residencial',11990,0,'expense','PIX','pending');add(m,24,'Projeto freelance',95000,7,'income','PIX','pending');}}return s;}

export function addCard(state,card){return saveCard(state,card);}
